44	    }
45	
46	    # Favicon (avoid 404 noise in logs)
47	    location = /favicon.ico {
48	        access_log off;
49	        log_not_found off;
50	        return 204;
51	    }
52	
53	    # Proxy all other requests to Django (gunicorn)
